def pcard(p,extra=''):
    return f'<a class="card" href="{p["url"]}" data-g="{p["g"]}" data-tags="{" ".join(p["tags"])}"{extra}><img src="/images/{p["img"]}.jpg" alt="{IMGALT[p["img"]]}" loading="lazy" width="400" height="190"><div class="in"><span class="lab">{p["group"]}</span><h3>{p["th"]}</h3><span class="en">{p["en"]}</span><p>{p["use"]}</p><span class="more">ดูรายละเอียดและ TDS</span></div></a>'
def acard(a):
    c,cat,t,ex,img,url=a
    return card(t,ex,img=img,lab=cat,href=url,soon=not url,alt=IMGALT[img])
