PFAQ=[('มาสเตอร์แบตช์ (Masterbatch) คืออะไร','เม็ดพลาสติกเข้มข้นที่ผสมสีหรือสารเติมแต่งไว้ล่วงหน้า ใช้ผสมกับเม็ดพลาสติกหลักในอัตราส่วนเล็กน้อยเพื่อให้ได้คุณสมบัติที่ต้องการ'),('ขอตัวอย่างไปทดลองก่อนสั่งผลิตได้ไหม','ได้ แจ้งชนิดงานและเครื่องจักรที่ใช้ ทีมเทคนิคจะเตรียมตัวอย่างและแนะนำอัตราการใช้ให้'),('BIONEX ใช้กับเครื่องจักรเดิมได้หรือไม่','ได้ BIONEX ออกแบบให้ขึ้นรูปได้กับอุปกรณ์การผลิตแบบดั้งเดิม')]
def plist(url,title,lead,crumbs,group=None):
    tabs=''.join(f'<button type="button" class="fbtn" data-group="{g}" aria-pressed="{"true" if (group or "all")==g else "false"}">{l}</button>' for g,l in [('all','ทั้งหมด (11)'),('polyolefins','พอลิโอเลฟินส์ (8)'),('bioplastics','พลาสติกชีวภาพ (3)')])
    chips=''.join(f'<button type="button" class="pbtn" data-tag="{t}" aria-pressed="false">{l}</button>' for t,l in [('block','ฟิล์มติดกัน'),('slip','ฟิล์มฝืด เปิดถุงยาก'),('static','ไฟฟ้าสถิต ฝุ่นเกาะ'),('rough','ผิวฟิล์มหยาบ'),('uv','เสื่อมจากแสงแดด'),('opaque','สีขาวไม่สม่ำเสมอ'),('bio','อยากลดพลาสติกจากปิโตรเลียม')])
    cards=''.join(pcard(p,'' if not group or p['g']==group else ' hidden') for p in PRODUCTS)
    shown=sum(1 for p in PRODUCTS if not group or p['g']==group)
    b=f'<section class="hero"><div class="wrap">{crumb(crumbs)}<div class="row" style="align-items:flex-end"><div class="txt"><h1>{title}</h1><p class="lead">{lead}</p></div><div class="box tint" style="flex:0 1 360px;display:flex;flex-direction:column;gap:12px"><h2 style="font-size:20px">ไม่แน่ใจว่าต้องใช้ตัวไหน</h2><p>เล่าปัญหาหน้างานให้วิศวกรฟัง แล้วเราจะแนะนำสูตรที่เหมาะให้</p><div><a class="btn btn-n" href="/contact/">นัดปรึกษาวิศวกร</a></div></div></div></div></section>'
    b+=f'<section class="sec" style="padding-top:40px" data-filter><div class="wrap" style="display:flex;flex-direction:column;gap:20px"><div class="chips" role="group" aria-label="กลุ่มผลิตภัณฑ์">{tabs}</div><div class="chips" role="group" aria-label="เลือกตามปัญหา" style="align-items:center"><span class="meta">เลือกตามปัญหาที่พบ:</span>{chips}</div><p class="meta" data-count>แสดง {shown} รายการ</p><div class="grid g4">{cards}</div></div></section>'
    b+=cta('ไม่เจอตัวที่ตรงโจทย์? เราพัฒนาสูตรเฉพาะให้ได้','ทีม R&D ออกสูตร ทดลองบนเครื่องจักรของคุณ และปรับจนผ่านเกณฑ์ ก่อนผลิตจริงทุกล็อต',(('ขอตัวอย่างสินค้า','btn-p','/contact/'),('ดูขั้นตอนร่วมพัฒนา','btn-g','/technical-services/co-development/')))
    b+=sec('คำถามเกี่ยวกับผลิตภัณฑ์',None,faq(PFAQ),'white')
    page(url,title.replace('<br>',''),lead,'products',b,crumbs=[(n,u) for n,u in crumbs],schema=[faq_schema(PFAQ),{"@context":"https://schema.org","@type":"ItemList","itemListElement":[{"@type":"ListItem","position":i+1,"url":SITE+p['url'],"name":p['th']} for i,p in enumerate(PRODUCTS) if not group or p['g']==group]}])
plist('/products/','ผลิตภัณฑ์เม็ดพลาสติก<br>และมาสเตอร์แบตช์','ยูนิค โพลีเมอร์ผลิตมาสเตอร์แบตช์และคอมปาวด์สำหรับงานพอลิโอเลฟินส์ 8 ชนิด และพลาสติกชีวภาพ BIONEX อีก 3 ชนิด ทุกตัวปรับสูตรให้เข้ากับเครื่องจักรและสินค้าของคุณได้',[('ผลิตภัณฑ์',None)])
plist('/products/polyolefins/','มาสเตอร์แบตช์และคอมปาวด์<br>สำหรับพอลิโอเลฟินส์','สารเติมแต่งที่แก้ปัญหาเฉพาะจุดในงานฟิล์มและบรรจุภัณฑ์ ตั้งแต่ความลื่น การป้องกันการยึดติด ไฟฟ้าสถิต ไปจนถึงการป้องกันรังสียูวี',[('ผลิตภัณฑ์','/products/'),('พอลิโอเลฟินส์',None)],'polyolefins')
plist('/products/bioplastics/','พลาสติกชีวภาพ BIONEX','คอมปาวด์ย่อยสลายได้ตามแนวทาง EN 13432 และคอมปาวด์ชีวมวลที่ลดคาร์บอน ทั้งหมดขึ้นรูปได้กับเครื่องจักรแบบดั้งเดิม',[('ผลิตภัณฑ์','/products/'),('พลาสติกชีวภาพ',None)],'bioplastics')
for p in PRODUCTS:
    gname='พอลิโอเลฟินส์' if p['g']=='polyolefins' else 'พลาสติกชีวภาพ'
    cr=[('ผลิตภัณฑ์','/products/'),(gname,f'/products/{p["g"]}/'),(p['th'],None)]
    ben=''.join(f'<li>{x}</li>' for x in p['ben'])
    apps=''.join(f'<span class="chip" style="background:var(--page);color:var(--text);font-weight:500">{a}</span>' for a in p['apps'])
    specs=[('เรซินพาหะ (Carrier)','[ใส่ชนิดเรซิน]','-'),('สารออกฤทธิ์ / ส่วนประกอบหลัก','[ใส่ข้อมูล]','-'),('ปริมาณสารออกฤทธิ์','[ใส่ %]','[ใส่วิธี]'),('ค่าการไหล (MFI)','[ใส่ค่า] g/10 min','ASTM D1238'),('อัตราการใช้แนะนำ','[ใส่ช่วง %]','-'),('บรรจุภัณฑ์','[ใส่ขนาดถุง]','-')]
    f=[(f'{p["th"]} ใช้ในอัตราเท่าไร','ขึ้นกับเรซิน ความหนาฟิล์ม และคุณสมบัติที่ต้องการ ทีมเทคนิคจะแนะนำอัตราที่เหมาะกับงานของคุณ'),('ขอตัวอย่างไปทดลองได้ไหม','ได้ แจ้งชนิดงานและเครื่องจักรที่ใช้ ทีมเทคนิคจะเตรียมตัวอย่างให้'),('มีเอกสาร TDS และ SDS หรือไม่','มี ดาวน์โหลดได้จากหน้านี้ หรือขอฉบับล่าสุดจากทีมขาย')]
    if p['slug']=='slip-masterbatch': f=[('Slip กับ Anti-Block ต่างกันอย่างไร','Slip ลดแรงเสียดทานที่ผิวให้ฟิล์มลื่น ส่วน Anti-Block ทำให้ผิวฟิล์มขรุขระระดับไมโครเพื่อไม่ให้ฟิล์มสองชั้นติดกัน งานส่วนใหญ่จึงใช้ทั้งสองตัวร่วมกัน'),('ทำไมฟิล์มยังฝืดทันทีหลังผลิต','สารช่วยลื่นต้องใช้เวลาเคลื่อนขึ้นมาที่ผิวฟิล์ม ค่าความลื่นจึงดีขึ้นหลังเก็บไว้ระยะหนึ่ง วิศวกรของเราช่วยวางแผนเวลาทดสอบให้ได้')]+f[1:]
    b=f'''<section class="hero"><div class="wrap">{crumb(cr)}<div class="row" style="align-items:flex-start"><div class="media"><img src="/images/{p['img']}.jpg" alt="{IMGALT[p['img']]}" width="520" height="400"></div><div class="txt"><div class="chips"><span class="chip">{gname}</span></div><h1>{p['th']}<br><span style="font-size:24px;font-weight:600;color:var(--muted)">{p['en']}</span></h1><div class="answer" style="background:var(--page)"><b style="font-size:15px;color:var(--primary)">สรุปสั้น</b><p style="font-size:17px">{p['sum']}</p></div><ul class="checks">{ben}</ul><div class="ctas"><a class="btn btn-p" href="#sample">ขอตัวอย่างไปทดลอง</a><a class="btn btn-o" href="#docs">ดาวน์โหลด TDS</a></div></div></div></div></section>'''
    b+=sec('เหมาะกับงาน',None,f'<div class="chips">{apps}</div>')
    b+=sec('ข้อมูลทางเทคนิค',None,table(['รายการ','ค่า','วิธีทดสอบ'],[[k,f'<span style="color:var(--primary)">{v}</span>',m] for k,v,m in specs],'คุณสมบัติทั่วไป')+'<p class="note">ค่าในตารางเป็นค่าทั่วไป ไม่ใช่สเปกสำหรับการรับรอง กรุณาดูเอกสาร TDS ฉบับล่าสุด</p>','white')
    b+=sec('เอกสารดาวน์โหลด',None,grid([f'<a class="card" href="#" style="flex-direction:row;align-items:center;gap:14px;padding:20px"><div class="ico" style="border-radius:12px;width:48px;height:48px">{I["doc"]}</div><div><h3 style="font-size:17px">{n}</h3><span class="meta">{m}</span></div></a>' for n,m in [('Technical Data Sheet (TDS)','PDF | [แนบไฟล์]'),('Safety Data Sheet (SDS)','PDF | [แนบไฟล์]'),('ใบรับรอง','[ระบุเอกสารที่มีจริง]')]],3),sid='docs')
    b+=sec('มักใช้คู่กับ',None,grid([pcard(PBY[r]) for r in p['rel']],3),'white')
    b+=f'<section class="sec" id="sample"><div class="wrap split"><div style="flex:1"><div class="shead"><h2>คำถามที่พบบ่อย</h2></div>{faq(f)}</div><div style="flex:0 1 440px">{form("ขอตัวอย่าง "+p["en"])}</div></div></section>'
    schema=[{"@context":"https://schema.org","@type":"Product","name":f'{p["th"]} ({p["en"]})',"description":p['sum'],"brand":{"@type":"Brand","name":"BIONEX" if p['g']=='bioplastics' and 'BIONEX' in p['th'] else "Unique Polymer"},"manufacturer":{"@type":"Organization","name":"Unique Polymer Co., Ltd."},"image":SITE+f'/images/{p["img"]}.jpg',"category":gname},faq_schema(f)]
    page(p['url'],f'{p["th"]} ({p["en"]})',p['sum'][:155],'products',b,crumbs=[(n,u) for n,u in cr],schema=schema,img=f'/images/{p["img"]}.jpg')
